//! hold SQL).
//!
//! Thin newtype over `backbone_orm::GenericCrudRepository<LoyaltyOrderPoints, backbone_orm::SoftDelete>`.
//! All standard CRUD methods are available via `Deref`.

use anyhow::Result;
use rust_decimal::Decimal;
use sqlx::{PgConnection, PgPool, Row};
use uuid::Uuid;

use crate::domain::entity::LoyaltyOrderPoints;

/// Table name for LoyaltyOrderPoints entities
pub const TABLE_NAME: &str = "promo.loyalty_order_points";

/// Repository for LoyaltyOrderPoints entities.
///
/// All standard CRUD, soft-delete, pagination, and bulk methods are
/// provided automatically via `Deref` to `backbone_orm::GenericCrudRepository`.
pub struct LoyaltyOrderPointsRepository(
    backbone_orm::GenericCrudRepository<LoyaltyOrderPoints, backbone_orm::SoftDelete>,
);

impl std::ops::Deref for LoyaltyOrderPointsRepository {
    type Target = backbone_orm::GenericCrudRepository<LoyaltyOrderPoints, backbone_orm::SoftDelete>;
    fn deref(&self) -> &Self::Target { &self.0 }
}

impl LoyaltyOrderPointsRepository {
    /// Create a new repository instance.
    pub fn new(pool: PgPool) -> Self {
        Self(backbone_orm::GenericCrudRepository::new(pool, TABLE_NAME))
    }
}

/// The grant leg a fresh order row is born carrying.
pub struct NewOrderGrantRow<'a> {
    pub company_id: Uuid,
    pub loyalty_program_id: Uuid,
    pub customer_id: Uuid,
    pub order_ref_type: &'a str,
    pub order_ref_id: Uuid,
    pub coupon_code_id: Option<Uuid>,
    pub grant_base_amount: Decimal,
    pub granted_points: Decimal,
    pub granted_at: chrono::DateTime<chrono::Utc>,
}

/// The spend leg a fresh order row is born carrying (an order that only SPENT — its member's points
/// were earned elsewhere).
pub struct NewOrderSpendRow<'a> {
    pub company_id: Uuid,
    pub loyalty_program_id: Uuid,
    pub customer_id: Uuid,
    pub order_ref_type: &'a str,
    pub order_ref_id: Uuid,
    pub spent_points: Decimal,
    pub spent_at: chrono::DateTime<chrono::Utc>,
}

/// The per-order accounting state the verbs read back.
#[derive(Debug, Clone, PartialEq)]
pub struct OrderPointsRow {
    pub id: Uuid,
    pub customer_id: Uuid,
    pub coupon_code_id: Option<Uuid>,
    pub grant_base_amount: Decimal,
    pub granted_points: Decimal,
    pub spent_points: Decimal,
    pub granted_reversed_points: Decimal,
    pub spent_reversed_points: Decimal,
    pub granted_at: Option<chrono::DateTime<chrono::Utc>>,
    pub spent_at: Option<chrono::DateTime<chrono::Utc>>,
}

/// Hand-written LoyaltyOrderPoints SQL. Lives here (not in the write service) per the module's
/// 4-layer rule: services orchestrate and own the unit of work, repositories hold the SQL.
///
/// Every method rides the CALLER'S transaction (the company scope is already bound — don't
/// re-bind here). The partial-unique upserts name the index's WHERE predicate in the conflict
/// target — the same pattern the entry ledger's claim uses.
impl LoyaltyOrderPointsRepository {
    /// Insert the order row born with its grant leg. `Ok(None)` = a row already exists for this
    /// order under this program (idempotent replay — read it back with [`Self::find_by_order_ref`]).
    pub async fn insert_grant(
        &self,
        conn: &mut PgConnection,
        g: &NewOrderGrantRow<'_>,
    ) -> Result<Option<Uuid>, sqlx::Error> {
        let row = sqlx::query(
            r#"
            INSERT INTO promo.loyalty_order_points
                (company_id, loyalty_program_id, customer_id, order_ref_type, order_ref_id,
                 coupon_code_id, grant_base_amount, granted_points, granted_at)
            VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
            ON CONFLICT (company_id, loyalty_program_id, order_ref_type, order_ref_id)
                WHERE (metadata->>'deleted_at') IS NULL
            DO NOTHING
            RETURNING id
            "#,
        )
        .bind(g.company_id)
        .bind(g.loyalty_program_id)
        .bind(g.customer_id)
        .bind(g.order_ref_type)
        .bind(g.order_ref_id)
        .bind(g.coupon_code_id)
        .bind(g.grant_base_amount)
        .bind(g.granted_points)
        .bind(g.granted_at)
        .fetch_optional(conn)
        .await?;
        Ok(row.map(|r| r.get("id")))
    }

    /// Insert the order row born with its spend leg (an order that only spent). `Ok(None)` = a row
    /// already exists — set the spend leg on it with [`Self::set_spent`] instead.
    pub async fn insert_spend(
        &self,
        conn: &mut PgConnection,
        s: &NewOrderSpendRow<'_>,
    ) -> Result<Option<Uuid>, sqlx::Error> {
        let row = sqlx::query(
            r#"
            INSERT INTO promo.loyalty_order_points
                (company_id, loyalty_program_id, customer_id, order_ref_type, order_ref_id,
                 spent_points, spent_at)
            VALUES ($1, $2, $3, $4, $5, $6, $7)
            ON CONFLICT (company_id, loyalty_program_id, order_ref_type, order_ref_id)
                WHERE (metadata->>'deleted_at') IS NULL
            DO NOTHING
            RETURNING id
            "#,
        )
        .bind(s.company_id)
        .bind(s.loyalty_program_id)
        .bind(s.customer_id)
        .bind(s.order_ref_type)
        .bind(s.order_ref_id)
        .bind(s.spent_points)
        .bind(s.spent_at)
        .fetch_optional(conn)
        .await?;
        Ok(row.map(|r| r.get("id")))
    }

    /// The order's points row, if any — the replay read and the reversal source of truth.
    pub async fn find_by_order_ref(
        &self,
        conn: &mut PgConnection,
        company_id: Uuid,
        loyalty_program_id: Uuid,
        order_ref_type: &str,
        order_ref_id: Uuid,
    ) -> Result<Option<OrderPointsRow>, sqlx::Error> {
        let row = sqlx::query(
            r#"
            SELECT id, customer_id, coupon_code_id, grant_base_amount, granted_points, spent_points,
                   granted_reversed_points, spent_reversed_points, granted_at, spent_at
            FROM promo.loyalty_order_points
            WHERE company_id = $1 AND loyalty_program_id = $2
              AND order_ref_type = $3 AND order_ref_id = $4
              AND (metadata->>'deleted_at') IS NULL
            "#,
        )
        .bind(company_id)
        .bind(loyalty_program_id)
        .bind(order_ref_type)
        .bind(order_ref_id)
        .fetch_optional(conn)
        .await?;
        Ok(row.map(|r| OrderPointsRow {
            id: r.get("id"),
            customer_id: r.get("customer_id"),
            coupon_code_id: r.get("coupon_code_id"),
            grant_base_amount: r.get("grant_base_amount"),
            granted_points: r.get("granted_points"),
            spent_points: r.get("spent_points"),
            granted_reversed_points: r.get("granted_reversed_points"),
            spent_reversed_points: r.get("spent_reversed_points"),
            granted_at: r.get("granted_at"),
            spent_at: r.get("spent_at"),
        }))
    }

    /// Record the grant leg on a pre-existing (spend-first) row. Idempotent-safe: only called when
    /// the ledger entry was freshly claimed.
    pub async fn set_granted(
        &self,
        conn: &mut PgConnection,
        company_id: Uuid,
        loyalty_program_id: Uuid,
        order_ref_type: &str,
        order_ref_id: Uuid,
        grant_base_amount: Decimal,
        granted_points: Decimal,
        granted_at: chrono::DateTime<chrono::Utc>,
    ) -> Result<(), sqlx::Error> {
        sqlx::query(
            r#"
            UPDATE promo.loyalty_order_points
            SET grant_base_amount = $5, granted_points = $6, granted_at = $7
            WHERE company_id = $1 AND loyalty_program_id = $2
              AND order_ref_type = $3 AND order_ref_id = $4
              AND (metadata->>'deleted_at') IS NULL
            "#,
        )
        .bind(company_id)
        .bind(loyalty_program_id)
        .bind(order_ref_type)
        .bind(order_ref_id)
        .bind(grant_base_amount)
        .bind(granted_points)
        .bind(granted_at)
        .execute(conn)
        .await?;
        Ok(())
    }

    /// Record the spend leg on a pre-existing (grant-first) row.
    pub async fn set_spent(
        &self,
        conn: &mut PgConnection,
        company_id: Uuid,
        loyalty_program_id: Uuid,
        order_ref_type: &str,
        order_ref_id: Uuid,
        spent_points: Decimal,
        spent_at: chrono::DateTime<chrono::Utc>,
    ) -> Result<(), sqlx::Error> {
        sqlx::query(
            r#"
            UPDATE promo.loyalty_order_points
            SET spent_points = $5, spent_at = $6
            WHERE company_id = $1 AND loyalty_program_id = $2
              AND order_ref_type = $3 AND order_ref_id = $4
              AND (metadata->>'deleted_at') IS NULL
            "#,
        )
        .bind(company_id)
        .bind(loyalty_program_id)
        .bind(order_ref_type)
        .bind(order_ref_id)
        .bind(spent_points)
        .bind(spent_at)
        .execute(conn)
        .await?;
        Ok(())
    }

    /// Advance the reversal counters by the derived legs. Over-reversal is refused HERE by the
    /// table's CHECKs (`granted_reversed_points <= granted_points`,
    /// `spent_reversed_points <= spent_points`) even for a caller that bypassed the service's own
    /// derivations.
    pub async fn add_reversal_counters(
        &self,
        conn: &mut PgConnection,
        company_id: Uuid,
        loyalty_program_id: Uuid,
        order_ref_type: &str,
        order_ref_id: Uuid,
        grant_leg: Decimal,
        spend_leg: Decimal,
    ) -> Result<(), sqlx::Error> {
        sqlx::query(
            r#"
            UPDATE promo.loyalty_order_points
            SET granted_reversed_points = granted_reversed_points + $5,
                spent_reversed_points = spent_reversed_points + $6
            WHERE company_id = $1 AND loyalty_program_id = $2
              AND order_ref_type = $3 AND order_ref_id = $4
              AND (metadata->>'deleted_at') IS NULL
            "#,
        )
        .bind(company_id)
        .bind(loyalty_program_id)
        .bind(order_ref_type)
        .bind(order_ref_id)
        .bind(grant_leg)
        .bind(spend_leg)
        .execute(conn)
        .await?;
        Ok(())
    }
}

backbone_core::impl_crud_repository!(LoyaltyOrderPointsRepository, LoyaltyOrderPoints, soft_delete);
